    assert client._has_pending_jobs() == False


def test_flush_callback(client):
    client.set_autoflush(False)

    @weave.op
    def op_1():
        time.sleep(0.01)

    op_1()

    def fake_logger(status):
        assert "job_counts" in status

    # flush with callback
